import {plans,money,findService} from './catalog.mjs';

export function homeMarkup({root='./'}={}) {
 const quote=(id,vehicle='car')=>root+'atendimento/?vehicle='+vehicle+'&service='+id;
 const photo=(name,alt,{position='50% 50%',eager=false}={})=>'<img src="'+root+'assets/'+name+'.webp" srcset="'+root+'assets/'+name+'-mobile.webp 560w, '+root+'assets/'+name+'.webp 1200w" sizes="(max-width:700px) 100vw, 600px" alt="'+alt+'" style="object-position:'+position+'" width="1200" height="1400" loading="'+(eager?'eager':'lazy')+'" '+(eager?'fetchpriority="high"':'')+' decoding="async">';
 const tiles=[
  ['essential','01','Lavagem','care-wash','Limpeza de rotina, com atenção a cada detalhe.','A partir de'],
  ['fullClean','02','Higienização','modern-interior','Um novo cuidado para o lado de dentro.',''],
  ['polishLight','03','Polimento','care-polish','Mais brilho. Menos marcas na pintura.','A partir de'],
  ['coating','04','Vitrificação','modern-mclaren','Preparação e proteção cerâmica da pintura.','']
 ];
 return `<section class="fn-hero" aria-labelledby="hero-title">
   <div class="fn-hero-heading"><span class="fn-eyebrow"><i></i> ESTÉTICA AUTOMOTIVA · CARROS & MOTOS</span><h1 id="hero-title">Seu veículo.<br>Em boa forma.</h1><p>O cuidado que faz você olhar de novo.<br>Da lavagem à proteção, com atenção de verdade.</p><div class="fn-hero-actions"><a class="fn-button fn-accent" href="${quote('premium')}">Escolher meu cuidado <span aria-hidden="true">↗</span></a><a class="fn-text-link" href="#care">Conhecer o Care <span aria-hidden="true">↓</span></a></div><span class="fn-hero-note">ATENDIMENTO PESSOAL. UM VEÍCULO POR VEZ.</span></div>
   <figure class="fn-hero-photo">${photo('modern-gt3','Detalhe da dianteira de um Porsche GT3 prateado',{position:'50% 64%',eager:true})}<figcaption><span>O detalhe faz a diferença.</span><span aria-hidden="true">↗</span></figcaption></figure>
   <div class="fn-hero-bottom"><span>LIMPAR <b>/</b> CORRIGIR <b>/</b> PROTEGER</span><span class="fn-hero-sign">FINE FORM / CAR CARE</span></div>
 </section>
 <section class="fn-care" id="care" aria-labelledby="care-title">
  <div class="fn-section-heading"><div><span class="fn-eyebrow">01 / CUIDADO CONTÍNUO</span><h2 id="care-title">Bom cuidado.<br><em>Todo mês.</em></h2></div><p>Seu carro na rotina certa.<br>Escolha o plano que acompanha você.</p></div>
  <div class="fn-care-layout"><div class="fn-care-banner"><div><span class="fn-care-brand">FINE FORM <b>CARE</b></span><h3>O capricho<br>vira rotina.</h3><p>Visitas combinadas.<br>Um veículo. Cuidado constante.</p></div><img src="${root}assets/detail-finish.webp" alt="Toalha de microfibra sobre a pintura vermelha de um carro" width="800" height="1200" loading="lazy" decoding="async"><span class="fn-photo-note">CUIDADO QUE CONTINUA.</span></div>
   <div class="fn-plan-grid">${plans.map(p=>`<a class="fn-plan ${p.id==='careFrequent'?'fn-plan-featured':''} ${p.vehicle==='moto'?'fn-plan-moto':''}" href="${root}atendimento/?mode=plan&vehicle=${p.vehicle}&plan=${p.id}"><div class="fn-plan-top"><span class="fn-plan-kind">${p.vehicle==='moto'?'PARA SUA MOTO':'PARA SEU CARRO'}</span>${p.id==='careFrequent'?'<span class="fn-plan-badge">MAIS CUIDADO</span>':'<span aria-hidden="true">↗</span>'}</div><div class="fn-plan-name"><h3>${p.name.replace('Care ','')}</h3><span class="fn-plan-visits">${p.visits} ${p.vehicle==='moto'?'lavagens':'visitas'} / mês</span></div><p class="fn-plan-price">${money(p.price)}<small>/mês</small></p><p class="fn-plan-desc">${p.description.replace('Uma Premium + uma Essencial','1 Premium + 1 Essencial').replace('Uma Premium + três Essenciais','1 Premium + 3 Essenciais').replace('Duas lavagens Moto Premium','2 lavagens Moto Premium').replace(' por mês.','')}</p><div class="fn-plan-foot"><span class="fn-plan-saving">Economize ${money(p.saving)}/mês</span><span class="fn-plan-cta">Escolher plano <span aria-hidden="true">↗</span></span></div></a>`).join('')}</div></div>
  <p class="fn-plan-note">Planos para um único veículo, com visitas combinadas. A assinatura é confirmada na conversa com Mateus.</p>
 </section>
 <section class="fn-services" id="cuidados" aria-labelledby="services-title"><div class="fn-section-heading"><div><span class="fn-eyebrow">02 / DO SEU JEITO</span><h2 id="services-title">Cada detalhe.<br><em>Um cuidado próprio.</em></h2></div><a class="fn-text-link" href="${root}atendimento/">Montar meu orçamento <span aria-hidden="true">↗</span></a></div><div class="fn-service-grid">${tiles.map(([id,index,title,image,description,prefix])=>`<a class="fn-service" href="${quote(id)}"><div class="fn-service-photo">${photo(image,title)}<span class="fn-service-index">${index}</span><span class="fn-service-arrow" aria-hidden="true">↗</span></div><div class="fn-service-copy"><h3>${title}</h3><p>${description}</p><span class="fn-service-price">${prefix?prefix+' ':''}<b>${money(findService(id).price)}</b></span></div></a>`).join('')}</div><a class="fn-moto-link" href="${quote('motoPremium','moto')}">${photo('modern-ducati','Ducati Panigale em iluminação vermelha')}<span><small>EM DUAS RODAS TAMBÉM.</small><b>Sua moto merece esse cuidado.</b><span>Moto Premium · ${money(findService('motoPremium').price)}</span></span><span class="fn-moto-arrow" aria-hidden="true">↗</span></a></section>
 <section class="fn-personal" id="sobre" aria-labelledby="personal-title"><div><span class="fn-eyebrow">03 / PRAZER, MATEUS.</span><h2 id="personal-title">Seu veículo.<br><em>Minha atenção.</em></h2></div><div><p>Você fala comigo, escolhe o cuidado e combina os detalhes antes de começar. Eu acompanho cada etapa, um veículo por vez.</p><button type="button" class="fn-button fn-black" data-contact>Vamos conversar <span aria-hidden="true">↗</span></button></div></section>
 <section class="fn-reviews" id="avaliacoes" aria-labelledby="reviews-title"><div class="fn-section-heading"><div><span class="fn-eyebrow">04 / EXPERIÊNCIAS</span><h2 id="reviews-title">Quem cuida,<br><em>deixa uma impressão.</em></h2></div></div><p id="reviews-summary">Avaliações dos nossos clientes.</p><div class="reviews-list" id="reviews-list" aria-live="polite"></div><button class="fn-button fn-black" id="reviews-more" type="button" hidden>Ver mais avaliações</button></section>`;
}
